# What /prop-traders had and /prop-firm-tracker didn't: merged there (audit n° 3, 1.1), /prop-traders redirects to it
def prop_blocks(lang, t):
    """What /prop-traders had, merged into /prop-firm-tracker (audit n° 3), on the design system."""
    import ui
    from pages8 import firm_row
    body = firm_row(lang, t)
    body += ui.split(t, T("Evaluations","Évaluations","Evaluaciones"), T("Keep your rules, especially on the hard days.","Respecte tes règles, surtout les jours difficiles.","Cumple tus reglas, sobre todo en los días difíciles."),
      T("Evaluations are rarely lost on the setup. They’re lost on the one trade that breaks the plan. Sweep makes that trade impossible to miss.","Les évaluations se perdent rarement sur le setup. Elles se perdent sur le trade qui brise le plan. Sweep rend ce trade impossible à manquer.","Las evaluaciones rara vez se pierden por el setup. Se pierden por la operación que rompe el plan. Sweep hace que esa operación sea imposible de ignorar."),
      [T("Rule checks on every trade, counted in your discipline","Vérification des règles sur chaque trade, comptée dans ta discipline","Revisión de reglas en cada operación, contada en tu disciplina"),
       T("What changes after a loss: size, frequency, results","Ce qui change après une perte : taille, fréquence, résultats","Qué cambia tras una pérdida: tamaño, frecuencia, resultados"),
       T("Violations ranked by what they cost you","Infractions classées selon ce qu’elles t’ont coûté","Infracciones ordenadas por lo que te costaron")],
      ui.frame_d("v6-04-discipline-psychology-d.webp", t(T("Discipline insights","Analyses de discipline","Análisis de disciplina")), m="v6-04-discipline-psychology-m.webp", t=t), flip=True, id_="evaluations")
    body += ui.split(t, T("Payouts and expenses","Payouts et dépenses","Payouts y gastos"), T("Payouts on one side. Costs on the other.","Les payouts d’un côté. Les coûts de l’autre.","Payouts por un lado. Costes por el otro."),
      T("Every payout from request to payment, every evaluation, reset and fee. The bottom line tells you whether your prop trading is a business.","Chaque payout de la demande au paiement, chaque évaluation, reset et frais. La ligne du bas te dit si ton trading prop est une entreprise.","Cada payout de la solicitud al pago, cada evaluación, reinicio y cuota. La última línea te dice si tu trading prop es un negocio."),
      [T("Planned, requested, approved, paid or rejected","Prévu, demandé, approuvé, payé ou refusé","Planificado, solicitado, aprobado, pagado o rechazado"),
       T("Evaluation, activation, reset, data and platform fees","Évaluation, activation, reset, frais de données et de plateforme","Evaluación, activación, reinicio, cuotas de datos y plataforma"),
       T("Net realized income = payouts − expenses","Revenu net réalisé = payouts − dépenses","Ingreso neto realizado = payouts − gastos")],
      ui.frame_d("v6-12-payouts-d.webp", t(T("Payouts and expenses summary","Résumé des payouts et dépenses","Resumen de payouts y gastos")), m="v6-12-payouts-m.webp", t=t), id_="payouts", more=f'<p class="fine" style="margin-top:16px">{t(MONEY_PLAN)} <a href="{href(lang, "payout-tracker.html")}">{t(T("Payout tracker","Suivi des payouts","Seguimiento de payouts"))} →</a></p>')
    shares = ('<div class="shares duo reveal">'
              + f'<figure>{share_img("share-payout", t(T("Payout received card, sample data","Carte payout reçu, données d’exemple","Tarjeta de payout recibido, datos de ejemplo")), 1080, 1350, "(max-width: 743px) 44vw, 360px")}</figure>'
              + f'<figure>{share_img("share-net", t(T("Net after fees card, sample data","Carte net après frais, données d’exemple","Tarjeta de neto tras comisiones, datos de ejemplo")), 1080, 1920, "(max-width: 743px) 34vw, 260px")}</figure></div>')
    body += ui.sec(ui.head(t, T("Share cards","Cartes à partager","Tarjetas para compartir"), T("Celebrate the payout. Show the real net.","Célèbre le payout. Montre le vrai net.","Celebra el payout. Muestra el neto real."),
                           T("Mark a payout as paid and a branded card opens on its own. Or share your net after fees, with your return on fees, and keep the amounts hidden if you prefer.","Marque un payout comme payé et une carte à ton image s’ouvre toute seule. Ou partage ton net après frais, avec ton rendement sur frais, en gardant les montants masqués si tu préfères.","Marca un payout como pagado y se abre sola una tarjeta con marca. O comparte tu neto tras comisiones, con tu retorno sobre comisiones, ocultando los importes si prefieres."), center=True)
                   + shares + f'<p class="cap">{t(T("The number of prop accounts depends on your plan.","Le nombre de comptes prop dépend de ton forfait.","El número de cuentas prop depende de tu plan."))}</p>', "a", "share", cls="show")
    return body

def prop_notice(lang, t):
    return f'<div class="notice">{ico(I["shield"])}<span>{t(T("Sweep is independent and is not affiliated with, endorsed by or connected to any proprietary trading firm. Firm names belong to their owners. Rules prefilled for guidance only: always check your firm’s current rules.","Sweep est indépendant et n’est affilié à aucune firme de trading pour compte propre, ni approuvé par elle. Les noms des firmes appartiennent à leurs propriétaires. Règles préremplies à titre indicatif : vérifie toujours les règles actuelles de ta firme.","Sweep es independiente y no está afiliado, respaldado ni vinculado a ninguna prop firm. Los nombres de las firmas pertenecen a sus propietarios. Reglas precargadas a título indicativo: verifica siempre las reglas actuales de tu firma."))}</span></div>'
